function Runtime:Changed(input)
    if self.ui._destroyed then return end
    if input.UserInputType==Enum.UserInputType.MouseMovement then
        self.pointer=self:MousePosition()
        if self.drag then self:UpdateDrag() else self:Hover() end
    elseif input.UserInputType==Enum.UserInputType.MouseWheel then
        self.pointer=self:MousePosition()
        if self.dirty then self:Draw() end
        if self.drag then return end
        local delta=input.Position.Z*30
        if self.popup then
            if Util.inside(self.popup.rect,self.pointer) then
                self.popup.scroll=Util.clamp((self.popup.scroll or 0)-delta,0,self.popup.maxScroll or 0); self:Dirty()
            end
            return
        end
        if self.window and self.window.Visible and not self.window.Minimized and self.navigationClip and Util.inside(self.navigationClip,self.pointer) then
            self.navigationScroll=Util.clamp((self.navigationScroll or 0)-delta,0,self.navigationMaxScroll or 0); self:Dirty(); return
        end
        local w=self.window
        if w and w.Visible and not w.Minimized and Util.inside(self.contentClip,self.pointer) then
            self:Blur(true)
            if self.ui._destroyed then return end
            self.capture=nil; w.Scroll=Util.clamp(w.Scroll-delta,0,w.MaxScroll); self.lastScroll=os.clock(); self:Dirty()
        end
    end
end
function Runtime:Ended(input)
    if self.ui._destroyed then return end
    if input.UserInputType==Enum.UserInputType.MouseButton1 then
        if self.drag and self.drag.role=='textselect' and self.box.CursorPosition==self.box.SelectionStart then self.box.SelectionStart=-1 end
        self.drag=nil; self.pressedHit=nil; self.scrollbarHold=false; self:Dirty()
    elseif input.UserInputType==Enum.UserInputType.Keyboard then
        local keys={}
        for c in pairs(self.held) do if c.Value==input.KeyCode.Name then table.insert(keys,c) end end
        for _,c in ipairs(keys) do self:ReleaseKey(c) end
    end
end
function Runtime:Notify(opts)
    local duration=Util.number(opts.Duration or 4,'Duration')
    assert(duration>0 and duration<=120,'Duration must be > 0 and <= 120 seconds')
    local title=Util.clean(opts.Title or 'Iris',256)
    local content=Util.clean(opts.Content or '',512)
    local cap=math.max(1,math.min(5,math.floor((self:Viewport().Y-24)/84)))
    while #self.notifications>=cap do table.remove(self.notifications,1) end
    table.insert(self.notifications,{Title=title,Content=content,expires=os.clock()+duration,alpha=0})
    self:Dirty()
end
function Runtime:Destroy()
    if self.scrollAction and self.actionService then self.actionService:UnbindAction(self.scrollAction) end
    self.scrollAction=nil
    if self.watchdog and task and type(task.cancel)=='function' and self.watchdog~=coroutine.running() then
        pcall(task.cancel,self.watchdog)
    end
    self.watchdog=nil
    self.edit=nil; self.capture=nil; self.drag=nil; self.popup=nil; self.retiringPopup=nil; self.pressedHit=nil
    for _,connection in ipairs(self.connections) do connection:Disconnect() end
    self.connections={}
    for c in pairs(self.held) do self:ReleaseKey(c) end
    if self.box then self.box:ReleaseFocus() end
    for _,frame in ipairs(self.hitFrames) do frame:Destroy() end
    self.hitFrames={}; self.hitCount=0; self.search=nil; self.history={}; self.sectionOffsets={}; self.controlOffsets={}
    if self.gui then self.gui:Destroy(); self.gui=nil end
    if self.renderer then self.renderer:Destroy() end
    self.hits={}; self.notifications={}; self.animations={}; self.visualStates={}; self.visualAnimations={}; self.window=nil
end
return Runtime
end
loaders["Internal.Shell"] = function()
local Util=require('Internal.Util')
local Theme=require('Internal.Theme')
local Shell={}
function Shell.Width(width)
    if width>=900 then return 320 end
    if width>=720 then return 256 end
    if width>=600 then return 200 end
    return 0
end
local function home(d,x,y,color,clip,z)
    d:Line(x,y+6,x+6,y,color,clip,z)
    d:Line(x+6,y,x+12,y+6,color,clip,z)
    d:Line(x+2,y+5,x+2,y+12,color,clip,z)
    d:Line(x+10,y+5,x+10,y+12,color,clip,z)
    d:Line(x+2,y+12,x+10,y+12,color,clip,z)
    d:Border(Util.rect(x+5,y+7,3,5),color,clip,z)
end
local function pageIcon(d,x,y,color,clip,z)
    d:Border(Util.rect(x+2,y,12,15),color,clip,z)
    d:Line(x+5,y+4,x+11,y+4,color,clip,z)
    d:Line(x+5,y+7,x+11,y+7,color,clip,z)
    d:Line(x+5,y+10,x+11,y+10,color,clip,z)
end
local function magnifier(d,x,y,width,color,clip,z)
    d:Round(Util.rect(x,y,width,width),width/2,color,clip,z)
    d:Round(Util.rect(x+1,y+1,width-2,width-2),(width-2)/2,Theme.field,clip,z+1)
    d:Line(x+width-2,y+width-1,x+width+2,y+width+4,color,clip,z+2)
end
