function Shell.Pane(rt,r,width)
    if width==0 or r.h<=0 then return end
    rt.renderer:Rect(Util.rect(r.x,r.y,width,r.h),Theme.navigation,nil,3)
end
function Shell.Sidebar(rt,r,width)
