-- the stock Windows 10 Settings app at 100% scaling. No visible Roblox GUI objects.
local fonts=Drawing and Drawing.Fonts or {}
local segoe=fonts.SegoeUI or fonts['Segoe UI']
local body=segoe or fonts.Plex or 2
local Theme={
    -- Surfaces
    bg=Color3.fromRGB(255,255,255),            -- ApplicationPageBackgroundThemeBrush
    chrome=Color3.fromRGB(242,242,242),        -- SystemControlPageBackgroundChromeLowBrush
    card=Color3.fromRGB(242,242,242),          -- SystemControlTransientBackgroundBrush fallback
    surface=Color3.fromRGB(242,242,242),
    field=Color3.fromRGB(255,255,255),         -- TextControlBackground
    -- Controls
    button=Color3.fromRGB(204,204,204),        -- ButtonBackground #33000000
    buttonHover=Color3.fromRGB(204,204,204),   -- PointerOver background is unchanged in Windows 10
    buttonPressed=Color3.fromRGB(153,153,153), -- #66000000
    buttonBorder=Color3.fromRGB(153,153,153),  -- ButtonBorderBrushPointerOver #66000000
    hover=Color3.fromRGB(230,230,230),         -- SystemListLowColor #19000000
    pressed=Color3.fromRGB(204,204,204),       -- SystemListMediumColor #33000000
    selection=Color3.fromRGB(230,230,230),     -- selected list row
    -- Lines and borders
    line=Color3.fromRGB(219,219,219),          -- SystemControlTransientBorderBrush (1903) #00000014
    controlBorder=Color3.fromRGB(153,153,153), -- TextControlBorderBrush #66000000
    borderHover=Color3.fromRGB(102,102,102),   -- TextControlBorderBrushPointerOver #99000000
    -- Text
    text=Color3.fromRGB(0,0,0),                -- SystemControlForegroundBaseHighBrush
    muted=Color3.fromRGB(102,102,102),         -- BaseMedium #99000000
    placeholder=Color3.fromRGB(153,153,153),   -- BaseMediumLow #66000000
    -- Accent (#0078D7 is the Windows 10 default; #0078D4 is Windows 11)
    accent=Color3.fromRGB(0,120,215),
    accentHover=Color3.fromRGB(77,161,227),    -- accent at 0.7 over white #4DA1E3
    accentPressed=Color3.fromRGB(0,90,158),    -- accent Dark1 #005A9E
    accentLow=Color3.fromRGB(153,201,239),     -- SystemControlHighlightListAccentLowBrush
    -- States
    disabled=Color3.fromRGB(204,204,204),      -- SystemControlDisabledBaseLowBrush
    disabledText=Color3.fromRGB(153,153,153),  -- SystemControlDisabledBaseMediumLowBrush
    white=Color3.new(1,1,1),
    checkBorder=Color3.fromRGB(51,51,51),      -- CheckBoxCheckBackgroundStrokeUnchecked #CC000000
    checkBorderHover=Color3.fromRGB(0,0,0),
    switchStroke=Color3.fromRGB(51,51,51),     -- ToggleSwitchStrokeOff #CC000000
    switchStrokeHover=Color3.fromRGB(0,0,0),
    togglePressed=Color3.fromRGB(102,102,102), -- ToggleSwitchFillOnPressed #99000000
    thumbHover=Color3.fromRGB(23,23,23),       -- SliderThumbBackgroundPointerOver #171717
    thumbPressed=Color3.fromRGB(204,204,204),
    sliderTrack=Color3.fromRGB(153,153,153),   -- SliderTrackFill #66000000
    scrollbar=Color3.fromRGB(153,153,153),
    scrollbarHover=Color3.fromRGB(102,102,102),
    closeHover=Color3.fromRGB(232,17,35),
    closePressed=Color3.fromRGB(196,15,31),
    -- Navigation pane
    navigation=Color3.fromRGB(242,242,242),
    navigationHover=Color3.fromRGB(230,230,230),
    navigationSelected=Color3.fromRGB(230,230,230),
    navigationPressed=Color3.fromRGB(204,204,204),
    -- Typography (Windows 10 type ramp: Caption 12, Body 14, Subtitle 20, Title 28)
    font=body, fontScale=segoe and 1 or 1.12, headingFont=fonts.SegoeUISemibold or fonts['Segoe UI Semibold'] or body,
    bodySize=14, captionSize=12, headingSize=20, pageSize=28, titleHeight=32,
    -- Measured Settings metrics
    metrics={
        padding=24, contentTop=44, contentBottom=16, scrollbarGutter=12,
        sectionHeight=44, pageHeight=64, sectionGap=24, rowHeight=72, labelHeight=22,
        sliderHeight=56, toggleHeight=56, buttonHeight=40, separatorHeight=28,
        fieldHeight=32, fieldWidth=280, controlTop=24, sliderWidth=320,
        itemHeight=32, popupPadding=4,
        toggleWidth=44, toggleTrackHeight=20, toggleKnob=12, toggleInset=4, toggleLabelGap=14,
        sliderTrack=2, sliderThumbWidth=8, sliderThumbHeight=24, sliderHit=32, sliderValueHeight=24,
        checkbox=20, checkGlyph=12,
        navRow=48, navText=48, navTop=194, navIcon=16, navBarWidth=4, navBarHeight=24,
        homeTop=40, searchTop=97, searchInset=16, headerTop=151,
        scrollbarWidth=12, scrollbarThumb=2, scrollbarThumbHover=6, scrollbarMinThumb=32,
    },
    motion={hover=.10,control=.15,popup=.16,scrollbar=.20},
}
function Theme.Mix(a,b,t)
    return Color3.new(a.R+(b.R-a.R)*t,a.G+(b.G-a.G)*t,a.B+(b.B-a.B)*t)
end
return Theme
end
loaders["Internal.Util"] = function()
local Util = {}
function Util.clamp(n, a, b) return math.max(a, math.min(b, n)) end
function Util.number(n, name)
    assert(type(n) == 'number' and n == n and math.abs(n) < math.huge, name .. ' must be finite')
    return n
end
function Util.copy(v)
    if typeof(v) ~= 'table' then return v end
    local result = {}
    for k, item in pairs(v) do result[k] = Util.copy(item) end
    return result
end
function Util.equal(a, b)
    if type(a) ~= type(b) then return false end
    if type(a) ~= 'table' then return a == b end
    for k, v in pairs(a) do if not Util.equal(v, b[k]) then return false end end
    for k in pairs(b) do if a[k] == nil then return false end end
    return true
end
function Util.string(s, name)
    assert(type(s) == 'string', name .. ' must be a string')
    assert(utf8.len(s), name .. ' must be valid UTF-8')
    return s
end
function Util.clean(s, limit)
    s = Util.string(s, 'Text'):gsub('[%c]', ' ')
    local length = utf8.len(s)
    if length > limit then s = s:sub(1, utf8.offset(s, limit + 1) - 1) end
    return s
end
function Util.prefix(s, length)
    if length <= 0 then return '' end
    return s:sub(1, (utf8.offset(s, length + 1) or (#s + 1)) - 1)
end
function Util.rect(x, y, w, h) return {x=x, y=y, w=w, h=h} end
function Util.intersect(a, b)
    if not b then return a end
    local x, y = math.max(a.x, b.x), math.max(a.y, b.y)
    local right, bottom = math.min(a.x+a.w,b.x+b.w), math.min(a.y+a.h,b.y+b.h)
    if right <= x or bottom <= y then return nil end
    return Util.rect(x,y,right-x,bottom-y)
end
function Util.inside(r, p)
    return r and p.X >= r.x and p.Y >= r.y and p.X < r.x+r.w and p.Y < r.y+r.h
end
function Util.contains(a, b)
    return not b or (a.x >= b.x and a.y >= b.y and a.x+a.w <= b.x+b.w and a.y+a.h <= b.y+b.h)
end
function Util.safe(callback, ...)
    if callback then
        local ok, message = pcall(callback, ...)
        if not ok then warn('[Iris Drawing callback] ' .. tostring(message)) end
    end
end
function Util.options(list)
    assert(type(list) == 'table', 'Options must be an array')
    local result, seen = {}, {}
    for key in pairs(list) do assert(type(key)=='number' and key%1==0 and key>=1 and key<=#list, 'Options must be a dense array') end
    assert(#list <= 500, 'Options supports at most 500 items')
    for i, name in ipairs(list) do
        Util.string(name, 'Option')
        assert(#name > 0 and not seen[name], 'Options must be unique nonempty strings')
        result[i], seen[name] = name, true
    end
    return result
end
function Util.live(ui) assert(not ui._destroyed, 'Iris Drawing has been destroyed') end
return Util
end
loaders["Library"] = function()
local Util=require('Internal.Util')
local Runtime=require('Internal.Runtime')
local Controls=require('Controls.Model')
local UI={Flags={},_flags={},_controls={},_destroyed=false,Version='1.0.20'}
local Window={}; Window.__index=Window
local Section={}; Section.__index=Section
local function options(opts,allowed)
    assert(type(opts)=='table','Expected an options table')
    for key in pairs(opts) do assert(allowed[key],'Unknown option: '..tostring(key)) end
end
local function vector(value,name)
    assert(typeof(value)=='Vector2',name..' must be Vector2')
    Util.number(value.X,name..'.X'); Util.number(value.Y,name..'.Y'); return value
end
function UI:_Runtime()
    if not self._runtime then self._runtime=Runtime.new(self) end
    return self._runtime
end
function UI:CreateWindow(opts)
    Util.live(self); options(opts,{Name=true,Size=true,Position=true,ToggleKey=true})
    assert(not self._window,'Version 1 supports one window per UI instance')
    local name=Util.clean(opts.Name or 'Iris',256)
    local size=vector(opts.Size or Vector2.new(960,720),'Size')
    assert(size.X>=320 and size.Y>=180,'Size minimum is 320 x 180')
    local toggle=opts.ToggleKey or 'RightShift'
    assert(type(toggle)=='string' and (toggle=='None' or Enum.KeyCode[toggle]) and toggle~='Unknown' and toggle~='Escape','ToggleKey must be a KeyCode name or None')
    local position=opts.Position and vector(opts.Position,'Position')
    local rt=self:_Runtime(); local view=rt:Viewport()
    position=position or Vector2.new(math.max(0,(view.X-size.X)/2),math.max(0,(view.Y-size.Y)/2))
    local w=setmetatable({UI=self,Name=name,RequestedSize=size,Size=size,Position=position,Visible=true,Minimized=false,Sections={},Scroll=0,MaxScroll=0},Window)
    self._toggleKey=toggle; self._window=w; rt.window=w; rt:ClampWindow()
    -- Paint during the caller's execution, before any deferred engine callback.
    rt.alpha=.35; rt.height=math.min(160,w.Size.Y)
    local ok,message=pcall(rt.Draw,rt)
    if not ok then
        rt:Destroy(); self._runtime=nil; self._window=nil
        error('Iris Drawing first frame failed: '..tostring(message))
    end
    rt:Dirty(); return w
end
function Window:AddSection(name)
    Util.live(self.UI)
    local section=setmetatable({UI=self.UI,Window=self,Name=Util.clean(name,256),Controls={}},Section)
    table.insert(self.Sections,section); self.UI._runtime:Dirty(); return section
end
function Window:SetVisible(visible)
    Util.live(self.UI); assert(type(visible)=='boolean','Visible must be boolean')
    if visible==self.Visible then return self end
    self.Visible=visible; self.UI._runtime:CancelInteraction(true)
    if not self.UI._destroyed then self.UI._runtime:Dirty() end
    return self
end
function Window:SetMinimized(minimized)
    Util.live(self.UI); assert(type(minimized)=='boolean','Minimized must be boolean')
    self.Minimized=minimized; self.UI._runtime:CancelInteraction(true)
    if not self.UI._destroyed then self.UI._runtime:ClampWindow(); self.UI._runtime:Dirty() end
    return self
end
function Window:SetSize(size)
    Util.live(self.UI); vector(size,'Size'); assert(size.X>=320 and size.Y>=180,'Size minimum is 320 x 180')
    self.RequestedSize=size; self.UI._runtime:CancelInteraction(true)
    if not self.UI._destroyed then self.UI._runtime:ClampWindow(); self.UI._runtime:Dirty() end
    return self
end
function Window:Destroy() self.UI:Destroy() end
for _,kind in ipairs({'Button','Toggle','Slider','Dropdown','MultiDropdown','Textbox','Keybind','ColorPicker','Label','Separator'}) do
    Section['Add'..kind]=function(section,opts)
        local c=Controls.Create(section,kind,opts)
        if kind=='Toggle' then c._visual=c.Value and 1 or 0
        elseif kind=='Slider' then c._visual=(c.Value-c.Min)/(c.Max-c.Min) end
        return c
    end
end
function UI:GetFlag(name)
    Util.live(self); assert(self._flags[name],'Unknown Flag: '..tostring(name))
    return self._flags[name]:GetValue()
end
function UI:SetFlag(name,value,silent)
    Util.live(self); assert(self._flags[name],'Unknown Flag: '..tostring(name))
    self._flags[name]:SetValue(value,silent); return self
end
function UI:GetConfig()
    Util.live(self)
    local flags={}
    for name,c in pairs(self._flags) do
        local v=c:GetValue()
        if c.Kind=='ColorPicker' then v={v.R,v.G,v.B} end
        flags[name]=v
    end
    return {Version=1,Flags=flags}
end
function UI:LoadConfig(config,silent)
    Util.live(self)
    assert(type(config)=='table' and config.Version==1 and type(config.Flags)=='table','Config must be {Version=1, Flags={...}}')
    for key in pairs(config) do assert(key=='Version' or key=='Flags','Unknown config field') end
    local values={}
    for name,value in pairs(config.Flags) do
        local c=self._flags[name]; assert(c,'Unknown Flag: '..tostring(name))
        if c.Kind=='ColorPicker' then
            assert(type(value)=='table' and #value==3,'Color config must be {r,g,b}')
            for key in pairs(value) do assert(key==1 or key==2 or key==3,'Color config must be an RGB array') end
            for i=1,3 do Util.number(value[i],'RGB'); assert(value[i]>=0 and value[i]<=1,'RGB values must be in [0,1]') end
            value=Color3.new(value[1],value[2],value[3])
        end
        values[c]=c:Validate(value)
    end
    local changed={}
    -- Stable creation order, never arbitrary pairs order, for callback dispatch.
    for _,c in ipairs(self._controls) do
        if values[c]~=nil and not Util.equal(c.Value,values[c]) then table.insert(changed,c) end
    end
    local rt=self._runtime
    if rt then rt:Blur(false); rt:ClosePopup(); rt.capture=nil end
    for _,c in ipairs(changed) do c:_Commit(values[c]) end
    for _,c in ipairs(changed) do
        if self._destroyed then break end
        if c.Kind=='Keybind' then rt:ReleaseKey(c) end
        if not silent and not self._destroyed then c:_Notify() end
    end
    return self
end
function UI:Notify(opts)
    Util.live(self); options(opts,{Title=true,Content=true,Duration=true})
    self:_Runtime():Notify(opts); return self
end
function UI:Destroy()
    if self._destroyed then return end
    self._destroyed=true
    if self._runtime then self._runtime:Destroy() end
    for _,c in ipairs(self._controls) do c.Callback=nil; c.OnChanged=nil; c._row=nil; c._anchor=nil end
    if self._window then
        for _,section in ipairs(self._window.Sections) do section.Controls={} end
        self._window.Sections={}
    end
    self._runtime=nil; self._window=nil; self._flags={}; self._controls={}; self.Flags={}
end
return UI
end
return require("Library")
